<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class OfficialDocumentController extends Controller{
 public function index(Request $r){$p=$r->attributes->get('academic_period');$q=DB::table('official_documents as d')->leftJoin('study_groups as g','g.id','=','d.study_group_id')->leftJoin('subjects as s','s.id','=','d.subject_id')->leftJoin('users as u','u.id','=','d.created_by')->where('d.academic_period_id',$p->id)->select('d.*','g.name as group_name','s.name as subject_name','u.name as author_name')->orderByDesc('d.id');return view('documents.index',['items'=>$q->get()]);}
 public function create(Request $r){$this->manage($r);$d=$r->validate(['type'=>'required|in:group,summary,attendance,attestation,student','study_group_id'=>'nullable|exists:study_groups,id','subject_id'=>'nullable|exists:subjects,id','student_id'=>'nullable|exists:students,id']);$p=$r->attributes->get('academic_period');$id=DB::transaction(function()use($r,$d,$p){$seq=(DB::table('official_documents')->max('id')??0)+1;$num=sprintf('CHIST-%s-%05d',date('Y'),$seq);$id=DB::table('official_documents')->insertGetId(array_merge($d,['number'=>$num,'academic_period_id'=>$p->id,'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]));$this->event($id,$r->user()->id,'created','Создан черновик');return $id;});return redirect()->route('documents.show',$id);}
 public function show(Request $r,$document){$d=DB::table('official_documents')->find($document);abort_if(!$d,404);$events=DB::table('official_document_events as e')->leftJoin('users as u','u.id','=','e.user_id')->where('e.official_document_id',$d->id)->select('e.*','u.name as user_name')->orderByDesc('e.id')->get();return view('documents.show',compact('d','events'));}
 public function sign(Request $r,$document){$this->manage($r);$d=DB::table('official_documents')->find($document);abort_if(!$d||$d->status!=='draft',409);DB::table('official_documents')->where('id',$document)->update(['status'=>'signed','signed_by'=>$r->user()->id,'signed_at'=>now(),'updated_at'=>now()]);$this->event($document,$r->user()->id,'signed','Документ подписан');return back()->with('success','Документ подписан.');}
 public function close(Request $r,$document){$this->manage($r);$d=DB::table('official_documents')->find($document);abort_if(!$d||$d->status!=='signed',409);$snap=$this->snapshot($d);DB::table('official_documents')->where('id',$document)->update(['status'=>'closed','closed_by'=>$r->user()->id,'closed_at'=>now(),'snapshot_json'=>json_encode($snap,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);$this->event($document,$r->user()->id,'closed','Документ закрыт, сохранён снимок данных');return back()->with('success','Документ закрыт и зафиксирован.');}
 public function print(Request $r,$document){$d=DB::table('official_documents')->find($document);abort_if(!$d,404);$data=$d->status==='closed'&&$d->snapshot_json?json_decode($d->snapshot_json,true):$this->snapshot($d);$this->event($d->id,$r->user()->id,'printed','Открыта печатная версия');return view('documents.print',compact('d','data'));}
 private function snapshot($d){$p=DB::table('academic_periods as p')->join('academic_years as y','y.id','=','p.academic_year_id')->where('p.id',$d->academic_period_id)->select('p.*','y.name as year_name')->first();$g=$d->study_group_id?DB::table('study_groups')->find($d->study_group_id):null;$sub=$d->subject_id?DB::table('subjects')->find($d->subject_id):null;$student=$d->student_id?DB::table('students')->find($d->student_id):null;$students=collect();if($g){$q=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$p->id)->where('m.study_group_id',$g->id)->where('m.status','active');$students=$q->exists()?$q->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$g->id)->where('status','active')->orderBy('last_name')->get();} $rows=[];foreach($students as $s){$rows[]=['id'=>$s->id,'fio'=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name),'result'=>$sub?DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id,'subject_id'=>$sub->id])->value('value'):null];}return ['organization'=>DB::table('organization_settings')->first(),'period'=>$p,'group'=>$g,'subject'=>$sub,'student'=>$student,'rows'=>$rows,'fixed_at'=>now()->toIso8601String()];}
 private function manage(Request $r){abort_unless($r->user()->canDo('reports.export')||$r->user()->canDo('semester.mark')||$r->user()->isSuperAdmin(),403);}
 private function event($id,$uid,$event,$details){DB::table('official_document_events')->insert(['official_document_id'=>$id,'user_id'=>$uid,'event'=>$event,'details'=>$details,'created_at'=>now(),'updated_at'=>now()]);}
}